import { path } from '@servicenow/sdk-build-core'
import { getMergedRecordUpdates, unzipInputArray } from '../test-utils'
import { createTestContext } from '../../../test-utils'

describe('AssignSubflowOutputs with Datapills Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('AssignSubflowOutputs -> Fluent to XML', () => {
        test('AssignSubflowOutputs with action output datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            // Verify flow logic instances were created
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Find the assignSubflowOutputs with action datapills
            const assignWithActionPill = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with action datapills'
            )
            expect(assignWithActionPill).toBeDefined()

            // Parse the values
            const valuesJson = unzipInputArray(assignWithActionPill.values) as any

            // Verify outputs array exists
            expect(valuesJson.outputsToAssign).toBeDefined()
            expect(valuesJson.outputsToAssign.length).toBeGreaterThan(0)

            // Find actionData output with action datapill
            const actionDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'actionData')
            expect(actionDataOutput).toBeDefined()
            expect(actionDataOutput.value).toContain('{{')
            expect(actionDataOutput.value).toContain('.__action_status__.message}}')
        })

        test('AssignSubflowOutputs with subflow input datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the assignSubflowOutputs with input datapills
            const assignWithInputPill = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with subflow input datapills'
            )
            expect(assignWithInputPill).toBeDefined()

            const valuesJson = unzipInputArray(assignWithInputPill.values) as any

            // Find inputData output with subflow input datapill
            const inputDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'inputData')
            expect(inputDataOutput).toBeDefined()
            expect(inputDataOutput.value).toContain('{{subflow.inputData}}')
        })

        test('AssignSubflowOutputs with template expression', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the assignSubflowOutputs with template
            const assignWithTemplate = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with template expressions'
            )
            expect(assignWithTemplate).toBeDefined()

            const valuesJson = unzipInputArray(assignWithTemplate.values) as any

            // Find message output with template expression
            const messageOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'message')
            expect(messageOutput).toBeDefined()

            // Should contain literal text
            expect(messageOutput.value).toContain('Processing completed for input:')

            // Should contain datapill
            expect(messageOutput.value).toContain('{{subflow.inputData}}')
        })
    })

    describe('AssignSubflowOutputs Structure and Format', () => {
        test('AssignSubflowOutputs outputs array structure', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const firstInstance = flowLogicInstances[0]

            const valuesJson = unzipInputArray(firstInstance.values) as any

            // Outputs array should exist
            expect(valuesJson.outputsToAssign).toBeDefined()
            expect(Array.isArray(valuesJson.outputsToAssign)).toBe(true)

            // Each output should have name, value, and displayValue
            valuesJson.outputsToAssign.forEach((output: any) => {
                expect(output.name).toBeDefined()
                expect(output.value).toBeDefined()
                expect(output.displayValue).toBeDefined()
            })
        })

        test('AssignSubflowOutputs displayValue mirrors value for datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignWithActionPill = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with action datapills'
            )

            const valuesJson = unzipInputArray(assignWithActionPill.values) as any

            // For datapills, displayValue should mirror value
            const actionDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'actionData')
            expect(actionDataOutput.value).toBe(actionDataOutput.displayValue)
        })

        test('AssignSubflowOutputs flow logic type', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // All instances should be assignSubflowOutputs type
            flowLogicInstances.forEach((instance: any) => {
                expect(instance).toBeDefined()
                // The flowLogic field should reference assignSubflowOutputs
            })
        })
    })

    describe('AssignSubflowOutputs with Datapills - Data Types', () => {
        test('AssignSubflowOutputs with string datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find instances with string datapills
            const stringDatapillInstances = flowLogicInstances.filter((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                return valuesJson.outputsToAssign.some((o: any) => o.value.includes('{{') && o.value.includes('}}'))
            })

            expect(stringDatapillInstances.length).toBeGreaterThan(0)

            // Verify string datapills are properly formatted
            stringDatapillInstances.forEach((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                const stringOutputs = valuesJson.outputsToAssign.filter((o: any) => o.value.includes('{{'))

                stringOutputs.forEach((output: any) => {
                    expect(output.value).toMatch(/{{[^}]+}}/)
                })
            })
        })

        test('AssignSubflowOutputs with literal values', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should support literal values alongside datapills
            const allOutputs = flowLogicInstances.flatMap((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                return valuesJson.outputsToAssign
            })

            // Some outputs should have literals (no datapills)
            const hasLiterals = allOutputs.some((o: any) => !o.value.includes('{{'))

            // Some outputs should have datapills
            const hasDatapills = allOutputs.some((o: any) => o.value.includes('{{'))

            expect(hasLiterals || hasDatapills).toBe(true)
        })
    })

    describe('AssignSubflowOutputs with Datapills - Template Expressions', () => {
        test('AssignSubflowOutputs template with embedded datapills', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignWithTemplate = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with template expressions'
            )

            const valuesJson = unzipInputArray(assignWithTemplate.values) as any
            const messageOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'message')

            // Template should have literal text
            expect(messageOutput.value).toContain('Processing completed for input:')

            // Template should have datapill
            expect(messageOutput.value).toContain('{{subflow.inputData}}')

            // Template structure: "text {{datapill}}"
            const textIndex = messageOutput.value.indexOf('Processing completed for input:')
            const datapillIndex = messageOutput.value.indexOf('{{')

            expect(textIndex).toBeLessThan(datapillIndex)
        })

        test('AssignSubflowOutputs template expression format', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignWithTemplate = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with template expressions'
            )

            const valuesJson = unzipInputArray(assignWithTemplate.values) as any
            const messageOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'message')

            // Should be a valid template string
            expect(typeof messageOutput.value).toBe('string')
            expect(messageOutput.value.length).toBeGreaterThan(0)

            // Should have proper datapill format
            expect(messageOutput.value).toMatch(/{{[^}]+}}/)
        })
    })

    describe('AssignSubflowOutputs with Datapills - Datapill Sources', () => {
        test('AssignSubflowOutputs with action output datapills format', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignWithActionPill = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with action datapills'
            )

            const valuesJson = unzipInputArray(assignWithActionPill.values) as any
            const actionDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'actionData')

            // Action output datapill format: {{action_label.output_field}}
            expect(actionDataOutput.value).toMatch(/{{[^.]+\.__action_status__.message}}/)
        })

        test('AssignSubflowOutputs with subflow input datapills format', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignWithInputPill = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with subflow input datapills'
            )

            const valuesJson = unzipInputArray(assignWithInputPill.values) as any
            const inputDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'inputData')

            // Subflow input datapill format: {{subflow_label.inputs.input_field}}
            expect(inputDataOutput.value).toContain('{{subflow.inputData}}')
        })

        test('AssignSubflowOutputs datapill sources variety', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Collect all output values
            const allOutputs = flowLogicInstances.flatMap((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                return valuesJson.outputsToAssign
            })

            // Should have datapills from action outputs
            const hasActionOutputs = allOutputs.some((o: any) => o.value.includes('.__action_status__.message}}'))
            expect(hasActionOutputs).toBe(true)

            // Should have datapills from subflow inputs
            const hasSubflowInputs = allOutputs.some((o: any) => o.value.includes('{{subflow.'))
            expect(hasSubflowInputs).toBe(true)
        })
    })

    describe('AssignSubflowOutputs with Datapills - Edge Cases', () => {
        test('Multiple assignSubflowOutputs in single subflow', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Should have at least 3 assignSubflowOutputs instances
            expect(flowLogicInstances.length).toBeGreaterThanOrEqual(3)

            // Each should have valid outputs
            flowLogicInstances.forEach((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                expect(valuesJson.outputsToAssign).toBeDefined()
                expect(valuesJson.outputsToAssign.length).toBeGreaterThan(0)
            })
        })

        test('AssignSubflowOutputs with single output', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Some instances should have only one output
            const singleOutputInstances = flowLogicInstances?.filter((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                return valuesJson.outputsToAssign.length === 1
            })

            expect(singleOutputInstances.length).toBeGreaterThan(0)
        })

        test('AssignSubflowOutputs output names unique within instance', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            expect(flowLogicInstances).toHaveLength(3)
            // Within each instance, output names should be unique
            flowLogicInstances?.forEach((instance: any) => {
                const valuesJson = unzipInputArray(instance.values) as any
                const outputNames = valuesJson.outputsToAssign?.map((o: any) => o.name)
                const uniqueNames = new Set(outputNames)

                expect(outputNames?.length).toBe(uniqueNames.size)
            })
        })

        test('AssignSubflowOutputs in subflow context', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'assign-subflow-outputs-datapills.now.ts',
                'flow-logics/fluent'
            )

            // Verify the flow is a subflow
            // expect(merged['sys_hub_action_type_definition']).toBeDefined()

            // Verify flow logic instances exist
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // All should be assignSubflowOutputs (specific to subflows)
            expect(flowLogicInstances.length).toBeGreaterThan(0)
        })
    })
})
